const NL = String.fromCharCode(10);
const inputData = $input.first().json || {};
const isManualTest =
  Object.keys(inputData).length === 0 ||
  (!inputData.body && !inputData.secret_key && !inputData.id_rapat && !inputData.agenda);

const root = inputData.body || inputData || {};
const expectedSecret = '<GANTI_TRANSKEP_WEBHOOK_KEY>';
const defaultCallbackUrl = 'https://script.google.com/macros/s/<GANTI_GAS_DEPLOYMENT_ID>/exec';
const incomingSecret = String(root.secret_key || '').trim();
const isAuthorized = isManualTest || (incomingSecret !== '' && incomingSecret === expectedSecret);

function parseIsoDate(rawStr) {
  const s = String(rawStr || '').trim();
  if (!s) return '';
  const mIso = s.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (mIso) return mIso[1] + '-' + mIso[2] + '-' + mIso[3];
  const months = {
    januari: '01', februari: '02', maret: '03', april: '04', mei: '05', juni: '06',
    juli: '07', agustus: '08', september: '09', oktober: '10', november: '11', nopember: '11', desember: '12'
  };
  const mIndo = s.toLowerCase().match(/(\d{1,2})\s+(januari|februari|maret|april|mei|juni|juli|agustus|september|oktober|november|nopember|desember)\s+(\d{4})/);
  if (mIndo) {
    const dd = String(parseInt(mIndo[1], 10)).padStart(2, '0');
    const mm = months[mIndo[2]] || '';
    if (mm) return mIndo[3] + '-' + mm + '-' + dd;
  }
  return '';
}

const idRapat = String(root.id_rapat || (isManualTest ? 'RPT-TEST-001' : '')).trim();
const agenda = String(root.agenda || (isManualTest ? 'Rapat Koordinasi Bulanan & Evaluasi Kinerja' : 'Rapat Kedinasan')).trim();
const hariTanggal = String(root.hari_tanggal || 'Rabu, 18 November 2026').trim();
const tglRapatIso = parseIsoDate(root.tgl_rapat_iso || hariTanggal) || new Date().toISOString().slice(0, 10);
const tempat = String(root.tempat || 'Ruang Rapat Pimpinan Pengadilan Agama Indramayu').trim();
const pemimpin = String(root.pemimpin || 'Ketua Pengadilan Agama Indramayu').trim();
const notulis = String(root.notulis || 'Notulis Rapat').trim();
const aiMode = String(root.ai_mode || 'merge').trim().toLowerCase() === 'replace' ? 'replace' : 'merge';

let pesertaList = [];
try {
  if (Array.isArray(root.peserta_list)) pesertaList = root.peserta_list;
  else if (typeof root.peserta_list === 'string' && root.peserta_list.trim()) {
    pesertaList = JSON.parse(root.peserta_list);
  }
} catch (e) {
  pesertaList = [];
}

let existingDraftObj = null;
try {
  if (root.existing_draft && typeof root.existing_draft === 'object') {
    existingDraftObj = root.existing_draft;
  } else if (typeof root.existing_draft === 'string' && root.existing_draft.trim().startsWith('{')) {
    existingDraftObj = JSON.parse(root.existing_draft);
  }
} catch (eDraft) {
  existingDraftObj = null;
}

const existingDraftText = existingDraftObj
  ? [
      existingDraftObj.dasar_notula ? 'Dasar Rapat (Draf Operator): ' + existingDraftObj.dasar_notula : '',
      existingDraftObj.pengarahan_umum ? 'Pengarahan Umum (Draf Operator): ' + existingDraftObj.pengarahan_umum : '',
      existingDraftObj.kesimpulan ? 'Kesimpulan (Draf Operator): ' + existingDraftObj.kesimpulan : '',
      Array.isArray(existingDraftObj.pembahasan) && existingDraftObj.pembahasan.length > 0
        ? 'Baris Pembahasan Operator (Tab 3): ' + JSON.stringify(existingDraftObj.pembahasan)
        : ''
    ].filter(Boolean).join(NL)
  : '';

const transcriptText = String(
  root.transcript_text ||
    root.ai_transcript ||
    (isManualTest
      ? 'Ketua memberikan pengarahan agar seluruh bagian mempercepat penyelesaian laporan bulanan. Sekretaris melaporkan progres pengadaan dan tindak lanjut pemeliharaan sarana sidang dengan target selesai akhir November 2026.'
      : '')
).trim();

const rawAudio = String(root.audio_base64 || root.audio_data || '').trim();
const cleanAudioBase64 = rawAudio.replace(/^data:audio\/[^;]+;base64,/i, '').replace(/\s+/g, '');
const audioDriveFileId = String(root.audio_drive_file_id || '').trim();
const audioFileName = String(root.audio_file_name || (audioDriveFileId ? 'rekaman_rapat.m4a' : 'rekaman_rapat.webm')).trim();
let audioMimeType = String(root.audio_mime_type || root.mime_type || 'audio/webm').split(';')[0].trim().toLowerCase() || 'audio/webm';
if (audioMimeType === 'audio/x-m4a' || audioMimeType === 'audio/m4a' || (/\.m4a$/i.test(audioFileName) && (!audioMimeType || audioMimeType === 'video/mp4'))) {
  audioMimeType = 'audio/mp4';
}
const audioSizeBytes = parseInt(root.audio_size_bytes || '0', 10) || 0;
const jobId = String(root.job_id || '').trim();
const callbackUrl = String(root.callback_url || defaultCallbackUrl).trim() || defaultCallbackUrl;
const isAsyncDriveAudio = Boolean(audioDriveFileId && jobId && !cleanAudioBase64);
const isUncompressedAudio = /wav|flac/i.test(audioMimeType) || /\.(wav|flac)$/i.test(audioFileName);
const needsFfmpeg = Boolean(
  isAsyncDriveAudio &&
  (audioSizeBytes > 100 * 1024 * 1024 || (isUncompressedAudio && audioSizeBytes > 20 * 1024 * 1024))
);

const pesertaInfoLines = Array.isArray(pesertaList)
  ? pesertaList
      .slice(0, 50)
      .map((p, idx) => {
        if (typeof p === 'string') return idx + 1 + '. ' + p;
        return (
          idx +
          1 +
          '. ' +
          String(p.nama || p.label || '-') +
          (p.jabatan ? ' (' + p.jabatan + ')' : '') +
          (p.nip ? ' [NIP: ' + p.nip + ']' : '')
        );
      })
      .join(NL)
  : '';

const fullSystemPrompt =
  'Kamu adalah Transkep AI, Notulis Eksekutif resmi Pengadilan Agama Indramayu (Mahkamah Agung RI).' +
  NL +
  'Tugasmu menganalisis rekaman audio rapat, mengidentifikasi pembicara, memadukannya dengan Draf Tab 3 Notulis (mode: ' + aiMode.toUpperCase() + '), dan menyusun JSON Notula Rapat Kedinasan terstruktur sesuai tata naskah dinas peradilan.' +
  NL +
  'ATURAN IDENTIFIKASI & WAKTU:' +
  NL +
  '1. Jangan pernah mengarang nama pembicara bila ragu. Jika tidak yakin siapa pembicaranya, gunakan "Pembicara #N (Belum Teridentifikasi — Bidang ...)".' +
  NL +
  '2. Klasifikasikan target & penyelesaian secara cerdas:' +
  NL +
  '   - EKSPLISIT: tanggal disebut jelas dalam rapat (isi target_tanggal_eksplisit / selesai_tanggal_eksplisit format YYYY-MM-DD).' +
  NL +
  '   - HARI_RAPAT: arahan rutin / kepatuhan / operasional harian yang berlaku mulai hari rapat.' +
  NL +
  '   - JANGKA_PENDEK: tindak lanjut administratif cepat (~5 hari kerja).' +
  NL +
  '   - JANGKA_MENENGAH: koordinasi lintas subbagian / surat-menyurat / evaluasi (~10 hari kerja).' +
  NL +
  '   - PROYEK_SARANA: penyiapan sarana/ruangan/aplikasi/pengadaan (~15 hari kerja).' +
  NL +
  'KELUARAN WAJIB HANYA JSON MURNI (tanpa teks pembuka/penutup) dengan skema berikut:' +
  NL +
  '{' +
  NL +
  '  "dasar_opsional": "string dasar pelaksanaan rapat jika disebut, atau string kosong",' +
  NL +
  '  "pengarahan_umum": "ringkasan pengarahan umum pimpinan rapat yang rapi & formal",' +
  NL +
  '  "kesimpulan": "kesimpulan/keputusan akhir rapat secara ringkas",' +
  NL +
  '  "transkrip_ringkas": "ringkasan padat jalannya rapat maksimal 4 kalimat",' +
  NL +
  '  "pembahasan": [' +
  NL +
  '    {' +
  NL +
  '      "pembicara_nama": "Nama & Jabatan Pembicara (cocokkan dengan daftar peserta atau Pembicara #N)",' +
  NL +
  '      "pembicara_nip": "NIP jika cocok peserta resmi, selain itu string kosong",' +
  NL +
  '      "pembicara_jabatan": "Jabatan pembicara",' +
  NL +
  '      "items": [' +
  NL +
  '        {' +
  NL +
  '          "uraian": "Uraian pokok bahasan / laporan",' +
  NL +
  '          "tindak_lanjut": "Langkah tindak lanjut / keputusan",' +
  NL +
  '          "target_kategori_waktu": "EKSPLISIT | HARI_RAPAT | JANGKA_PENDEK | JANGKA_MENENGAH | PROYEK_SARANA",' +
  NL +
  '          "target_tanggal_eksplisit": "YYYY-MM-DD jika disebut, selain itu string kosong",' +
  NL +
  '          "penanggung_jawab": "Pihak / jabatan penanggung jawab",' +
  NL +
  '          "selesai_kategori_waktu": "EKSPLISIT | HARI_RAPAT | JANGKA_PENDEK | JANGKA_MENENGAH | PROYEK_SARANA",' +
  NL +
  '          "selesai_tanggal_eksplisit": "YYYY-MM-DD jika disebut, selain itu string kosong"' +
  NL +
  '        }' +
  NL +
  '      ]' +
  NL +
  '    }' +
  NL +
  '  ]' +
  NL +
  '}';

const hasAudioInput = Boolean(cleanAudioBase64 || isAsyncDriveAudio);
const cleanPrompt =
  '=== IDENTITAS RAPAT KEDINASAN PA INDRAMAYU ===' +
  NL +
  'ID Rapat: ' + (idRapat || '-') +
  NL +
  'Agenda / Acara: ' + agenda +
  NL +
  'Hari / Tanggal: ' + hariTanggal + ' (ISO: ' + tglRapatIso + ')' +
  NL +
  'Tempat: ' + tempat +
  NL +
  'Pimpinan Rapat: ' + pemimpin +
  NL +
  'Notulis: ' + notulis +
  NL +
  'Mode Smart Merge: ' + (aiMode === 'replace' ? 'SUSUN ULANG TOTAL (REPLACE)' : 'LENGKAPI & SEMPURNAKAN DRAF TAB 3 (MERGE)') +
  NL +
  (pesertaInfoLines ? NL + 'Daftar Peserta Terdaftar:' + NL + pesertaInfoLines + NL : '') +
  (existingDraftText ? NL + 'Draf Notula Operator Saat Ini (Tab 3):' + NL + existingDraftText + NL : '') +
  (transcriptText ? NL + 'Konteks / Catatan Tambahan:' + NL + transcriptText + NL : '') +
  NL +
  (hasAudioInput
    ? 'Analisis audio rapat ini beserta konteks Tab 3, lalu kembalikan JSON skema multi-baris Notula Rapat PA Indramayu.'
    : 'Sempurnakan / susun draf Notula Rapat di atas menjadi JSON skema multi-baris Notula Rapat PA Indramayu dalam Bahasa Indonesia kedinasan yang baku.');

const parts = [];
if (cleanAudioBase64) {
  parts.push({
    inline_data: {
      mime_type: audioMimeType,
      data: cleanAudioBase64,
    },
  });
}
parts.push({ text: cleanPrompt });

const geminiRequestBody = {
  system_instruction: {
    parts: [{ text: fullSystemPrompt }],
  },
  contents: [
    {
      role: 'user',
      parts,
    },
  ],
  generationConfig: {
    temperature: 0.2,
    maxOutputTokens: 8192,
    responseMimeType: 'application/json',
  },
};

return [
  {
    json: {
      isAuthorized,
      isManualTest,
      isAsyncDriveAudio,
      needsFfmpeg,
      job_id: jobId,
      callback_url: callbackUrl,
      secret_key: expectedSecret,
      id_rapat: idRapat,
      agenda,
      hari_tanggal: hariTanggal,
      tgl_rapat_iso: tglRapatIso,
      tempat,
      pemimpin,
      notulis,
      aiMode,
      pesertaList,
      pesertaInfoLines,
      existingDraftObj,
      existingDraftText,
      transcriptText,
      audioAttached: hasAudioInput,
      audio_drive_file_id: audioDriveFileId,
      audioFileName,
      audioMimeType,
      audioSizeBytes,
      cleanPrompt,
      fullSystemPrompt,
      geminiRequestBody,
    },
  },
];

const NL = String.fromCharCode(10);
const ctx = $('Validasi & Siapkan Prompt Notulen (Code)').first().json || {};
const item = $input.first().json || {};

if (item.error) {
  const errMsg = String(item.error.message || item.error || 'Gemini API gagal merespons.');
  return [
    {
      json: {
        status: 'error',
        id_rapat: String(ctx.id_rapat || ''),
        model: 'models/gemini-3.8-flash',
        message: 'Kendala Gemini Multimodal API: ' + errMsg,
      },
    },
  ];
}

function tryParseBalancedJson(str) {
  if (!str) return null;
  const s = String(str).trim();
  try { return JSON.parse(s); } catch (e0) {}
  const firstBrace = s.indexOf('{');
  if (firstBrace === -1) return null;
  const candidate = s.slice(firstBrace);
  const lastBrace = candidate.lastIndexOf('}');
  if (lastBrace > 0) {
    const sliced = candidate.slice(0, lastBrace + 1).replace(/,\s*([}\]])/g, '$1');
    try { return JSON.parse(sliced); } catch (e1) {}
  }
  let fixed = candidate.replace(/,\s*$/, '');
  const stack = [];
  let inString = false;
  let escaped = false;
  for (let i = 0; i < fixed.length; i++) {
    const ch = fixed[i];
    if (escaped) { escaped = false; continue; }
    if (ch === '\\' && inString) { escaped = true; continue; }
    if (ch === '"') { inString = !inString; continue; }
    if (inString) continue;
    if (ch === '{' || ch === '[') stack.push(ch);
    else if (ch === '}' && stack[stack.length - 1] === '{') stack.pop();
    else if (ch === ']' && stack[stack.length - 1] === '[') stack.pop();
  }
  if (inString) fixed += '"';
  fixed = fixed.replace(/,\s*$/, '');
  while (stack.length > 0) {
    const open = stack.pop();
    fixed = fixed.replace(/,\s*$/, '') + (open === '{' ? '}' : ']');
  }
  fixed = fixed.replace(/,\s*([}\]])/g, '$1');
  try { return JSON.parse(fixed); } catch (e2) {}
  return null;
}

function extractGeminiJson(item) {
  if (!item || typeof item !== 'object') return { parsed: null, rawText: '' };
  const textCandidates = [];
  if (typeof item.data === 'string' && item.data.includes('data:')) {
    const sseNonThought = [];
    const sseAll = [];
    for (const line of item.data.split(/\r?\n/)) {
      const m = line.match(/^data:\s*(.+)$/);
      if (!m) continue;
      const payload = m[1].trim();
      if (!payload || payload === '[DONE]') continue;
      try {
        const chunk = JSON.parse(payload);
        const cParts = chunk && chunk.candidates && chunk.candidates[0] && chunk.candidates[0].content && Array.isArray(chunk.candidates[0].content.parts)
          ? chunk.candidates[0].content.parts
          : [];
        for (const p of cParts) {
          if (p && typeof p.text === 'string') {
            sseAll.push(p.text);
            if (!p.thought) sseNonThought.push(p.text);
          }
        }
      } catch (eSse) {}
    }
    const sseCombined = (sseNonThought.length > 0 ? sseNonThought : sseAll).join('');
    if (sseCombined.trim()) textCandidates.push(sseCombined);
  }
  try {
    const parts = item.candidates && item.candidates[0] && item.candidates[0].content && Array.isArray(item.candidates[0].content.parts)
      ? item.candidates[0].content.parts
      : [];
    for (const p of parts) {
      if (p && !p.thought && typeof p.text === 'string' && p.text.trim()) {
        textCandidates.push(p.text);
      }
    }
    if (textCandidates.length === 0) {
      for (const p of parts) {
        if (p && typeof p.text === 'string' && p.text.trim()) {
          textCandidates.push(p.text);
        }
      }
    }
  } catch (eC) {}
  if (textCandidates.length === 0 && (item.output || item.text)) {
    textCandidates.push(String(item.output || item.text || ''));
  }

  for (let i = textCandidates.length - 1; i >= 0; i--) {
    const clean = String(textCandidates[i] || '').replace(/```(?:json)?/gi, '').trim();
    const obj = tryParseBalancedJson(clean);
    if (obj && typeof obj === 'object') {
      return { parsed: obj, rawText: clean };
    }
  }

  const joined = textCandidates.join('\n').replace(/```(?:json)?/gi, '').trim();
  const parsedJoined = tryParseBalancedJson(joined);
  if (parsedJoined && typeof parsedJoined === 'object') {
    return { parsed: parsedJoined, rawText: joined };
  }
  if (typeof item.pengarahan_umum === 'string' || Array.isArray(item.pembahasan) || Array.isArray(item.pembicara_terdeteksi)) {
    return { parsed: item, rawText: JSON.stringify(item) };
  }
  return { parsed: null, rawText: joined };
}

const extracted = extractGeminiJson(item);
const parsed = extracted.parsed;

if (!parsed || typeof parsed !== 'object') {
  return [
    {
      json: {
        status: 'error',
        id_rapat: String(ctx.id_rapat || ''),
        model: 'models/gemini-3.8-flash',
        message: 'Output Gemini tidak berbentuk JSON valid.',
        raw_preview: String(extracted.rawText || '').slice(0, 500),
      },
    },
  ];
}

const SKB_HOLIDAYS = {
  '2026-01-01': 1, '2026-01-16': 1, '2026-02-16': 1, '2026-02-17': 1,
  '2026-03-18': 1, '2026-03-19': 1, '2026-03-20': 1, '2026-03-21': 1, '2026-03-22': 1, '2026-03-23': 1, '2026-03-24': 1,
